$root=dirname(__DIR__);$target='C:/xampp/htdocs/boticav1';require $target.'/config/database.php';$db=appPdoConnection();$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
