$header=$target.'/views/header.php';$html=file_get_contents($header);$menuLink='<li><a href="/views/support.php"><i class="fa fa-life-ring"></i> Centro de soporte</a></li>';if(strpos($html,$menuLink)!==false){copy($header,$backup.'/header.php');$html=str_replace($menuLink,'',$html);file_put_contents($header.'.support-tmp',$html);rename($header.'.support-tmp',$header);}

